#include <iostream>

int main() {
    std::array<int, 3> datos{2, 4, 6};
    const std::array<int, 3> vista = datos;
    std::array<int, 3> copia = datos;
    int cantidad = 0;

    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int tipo = 0;
        if (!(std::cin >> tipo)) {
            return 1;
        }
        if (tipo == 1) {
            int indice = 0;
            int valor = 0;

            if (!(std::cin >> indice >> valor)) {
                return 1;
            }
            // Valida y modifica datos únicamente cuando se acepte.
            std::cout << "Pendiente:" << indice << ',' << valor;
        } else if (tipo == 2) {
            // Guarda en copia los valores actuales de datos.
            std::cout << "Pendiente";
        } else if (tipo == 3) {
            // Restaura datos desde copia, sin intentar asignar a vista.
            std::cout << "Pendiente";
        } else {
            return 1;
        }
        std::cout << ";Vista:" << vista[0] << ',' << vista[1] << ',' << vista[2]
                  << ";Copia:" << copia[0] << ',' << copia[1] << ',' << copia[2] << '\n';
    }

    return 0;
}

