#include <array>
#include <cstddef>
#include <iostream>

int main() {
    std::array<int, 3> datos{2, 4, 6};
    const std::array<int, 3>& vista = datos;
    std::array<int, 3> copia = datos;
    int cantidad = 0;

    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int tipo = 0;
        if (!(std::cin >> tipo)) {
            return 1;
        }
        if (tipo == 1) {
            int indice = 0;
            int valor = 0;

            if (!(std::cin >> indice >> valor)) {
                return 1;
            }
            if (indice < 0 || indice > 2 || valor < 0 || valor > 9) {
                std::cout << "Rechazo";
            } else {
                datos[static_cast<std::size_t>(indice)] = valor;
                std::cout << "Cambio";
            }
        } else if (tipo == 2) {
            copia = datos;
            std::cout << "Guardado";
        } else if (tipo == 3) {
            datos = copia;
            std::cout << "Restaurado";
        } else {
            return 1;
        }
        std::cout << ";Vista:" << vista[0] << ',' << vista[1] << ',' << vista[2]
                  << ";Copia:" << copia[0] << ',' << copia[1] << ',' << copia[2] << '\n';
    }

    return 0;
}

